create table public.challenges (id uuid primary key default gen_random_uuid(), activity_id uuid not null unique references public.activities(id) on delete restrict, title text not null, description text, configuration jsonb, xp_reward integer not null default 0 check (xp_reward >= 0), status text not null default 'draft', created_at timestamptz not null default now(), updated_at timestamptz not null default now());;
